            new_board.append(board[i+8][:])

        # Generate the bottom 8 rows (Rows 56-63)
        # Heuristic: Copy the pattern from the top boundary or generate standard floor
        # Since we don't know the exact map below, we use a safe filler.
        # Often, scrolling down reveals new terrain. 
        # We will replicate the "start" pattern of the bottom rows if they exist, 
        # or fill with G/c/B mix similar to the top.
        # Let's fill with G for border and c for interior to match the general style.
        for i in range(8):
            row_idx = 56 + i
            # Create a row similar to Row 0 (which was G) but maybe different?
            # Let's just fill with G to indicate empty space/new area.
            # Or better, copy Row 0 of the NEW board (which was Row 8 old) if it's a loop?
            # Unlikely. Let's stick to filling with 'G' for safety, 
            # but looking at Trans 0 mismatches, Row 0 became 'c'.
            # So Old Row 8 was 'c'. 
            # If we run out of map, maybe it repeats?
            # Let's fill the bottom with the same pattern as the top of the new board?
            # No, that would make a loop.
            # I will fill the bottom 8 rows with 'G' (Dark Gray) as a placeholder for unknown territory.
            new_board.append(['G'] * 64)

        board = new_board

    elif action == "LEFT":
        # 1. Move Blue/Pink Diamond Entity
        # Look for the pattern N, b, P, M in Rows 33-37

        found = False
        min_r, max_r = 33, 37
        min_c, max_c = 20, 40

