                row_vals.append(v)
            block_data.append(row_vals)

        if found:
            # Shift left by 1 column
            for r_idx, row_vals in enumerate(block_data):
                target_r = min_r + r_idx
                for c_idx in range(len(row_vals)):
                    target_c = min_c + c_idx
                    # Value comes from the right neighbor
                    if c_idx + 1 < len(row_vals):
                        new_val = row_vals[c_idx + 1]
                    else:
                        new_val = get(target_r, max_c + 1)
                    set(target_r, target_c, new_val)

        # 2. Update Score Bar
        score_r = 63
