            set(34, 29, 'g')
            set(35, 25, 'g')
            set(35, 30, 'g')

        elif mr == 28 and mc == 56:
            # Swap R and W in the Orange/Snake region (Top Left)
            min_r, max_r = 20, 31
            min_c, max_c = 0, 20

            block = []
            for r in range(min_r, max_r+1):
                row = []
                for c in range(min_c, max_c+1):
                    row.append(get(r,c))
                block.append(row)

            new_block = []
            for row in block:
                new_row = []
                for val in row:
                    if val == 'R': new_row.append('W')
