def predict(board_lines, action):
    # Parse board
    board = [list(row) for row in board_lines]
    H = len(board)
    W = len(board[0])

    def find_player():
        min_r, max_r, min_c, max_c = H, 0, W, 0
        found = False
        for r in range(H):
            for c in range(W):
                if board[r][c] == 'N' or board[r][c] == 'W':
                    if not found:
                        min_r, max_r, min_c, max_c = r, r, c, c
                        found = True
                    else:
                        min_r = min(min_r, r)
                        max_r = max(max_r, r)
                        min_c = min(min_c, c)
                        max_c = max(max_c, c)

        if not found:
            return None

        # Filter out small noise if any, but assume largest cluster is player
        # Simple heuristic: Return bounding box
        return (min_r, max_r, min_c, max_c)

    def clear_area(r1, r2, c1, c2, char='w'):
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                if 0 <= r < H and 0 <= c < W:
                    board[r][c] = char

    def draw_player(r, c):
        # Face Top
        for col in range(c, c + 4):
            if 0 <= r < H and 0 <= col < W:
                board[r][col] = 'W'
        # Body Below
        for row in range(r + 1, r + 4):
            for col in range(c, c + 4):
                if 0 <= row < H and 0 <= col < W:
                    board[row][col] = 'N'

    def update_ui():
        for c in range(W - 1, -1, -1):
            if board[H - 1][c] == 'P':
                board[H - 1][c] = 'c'
                break

    def draw_obstacle_pattern(r_start, c_start, w=4, h=4):
        for dr in range(h):
            for dc in range(w):
                r = r_start + dr
                c = c_start + dc
                if 0 <= r < H and 0 <= c < W:
                    if dr == 0 or dr == h-1 or dc == 0 or dc == w-1:
                        board[r][c] = 'c'
                    else:
                        board[r][c] = 'b'

    p_box = find_player()

    if action == 'SPACE':
        non_w_count = sum(1 for r in board for cell in r if cell != 'w')

        # Heuristic for Initialization vs Reset vs Cleanup
        # If very few items, Init.
        if non_w_count < 50:
            # CLEAR EVERYTHING FIRST
            for r in range(H):
                for c in range(W):
                    board[r][c] = 'w'

            # Draw Player
            draw_player(8, 12)

            # Draw Orange
            for r in range(36, 40):
                for c in range(24, 28):
                    board[r][c] = 'O'

            # Draw Left Enemy (Rows 28-36, Cols 12-19)
            for r in range(28, 37): # 28 to 36 inclusive
                for c in range(12, 20): # 12 to 19 inclusive
                    if r == 28 or r == 36:
                        board[r][c] = 'b'
                    elif c == 12 or c == 19:
                        board[r][c] = 'b'
                    else:
                        board[r][c] = 'g'

            # Draw Obstacles
            # Block at 20,40
            draw_obstacle_pattern(20, 40)
            # Block at 24,48
            draw_obstacle_pattern(24, 48)
            # Block at 32,48
            draw_obstacle_pattern(32, 48)
            # Block at 40,44
            draw_obstacle_pattern(40, 44)

            # Block at 28,36 (The one that replaced the start board WWWW)
            draw_obstacle_pattern(28, 36)

            # Fill UI Bar
            for c in range(54, 64):
                if c < W:
                    board[63][c] = 'P'

            return [''.join(row) for row in board]

        else:
            has_B = any('B' in ''.join(row) for row in board)
            if has_B:
                # Cleanup T11 style
                for r in range(H):
                    for c in range(W):
                        if board[r][c] == 'B':
                            board[r][c] = 'c'
                update_ui()
                return [''.join(row) for row in board]
            else:
                # Reset T14 style
                # Same as Init
                for r in range(H):
                    for c in range(W):
                        board[r][c] = 'w'
                draw_player(8, 12)
                for r in range(36, 40):
                    for c in range(24, 28):
                        board[r][c] = 'O'
                for r in range(28, 37):
                    for c in range(12, 20):
                        if r == 28 or r == 36:
                            board[r][c] = 'b'
                        elif c == 12 or c == 19:
                            board[r][c] = 'b'
                        else:
                            board[r][c] = 'g'
                draw_obstacle_pattern(20, 40)
                draw_obstacle_pattern(24, 48)
                draw_obstacle_pattern(32, 48)
                draw_obstacle_pattern(40, 44)
                draw_obstacle_pattern(28, 36)
                for c in range(54, 64):
                    if c < W:
                        board[63][c] = 'P'
                return [''.join(row) for row in board]

    elif p_box:
        r1, r2, c1, c2 = p_box
        nr1, nc1 = r1, c1

        if action == 'UP':
            nr1 -= 1
        elif action == 'DOWN':
            nr1 += 1
        elif action == 'LEFT':
            nc1 -= 1
        elif action == 'RIGHT':
            nc1 += 1

        if 0 <= nr1 and nr1 + 3 < H and 0 <= nc1 and nc1 + 3 < W:
            orange_locs = []
            for r in range(H):
                for c in range(W):
                    if board[r][c] == 'O':
                        orange_locs.append((r,c))

            kicked = False
            if orange_locs and action == 'RIGHT':
                o_min_r = min([p[0] for p in orange_locs])
                o_max_r = max([p[0] for p in orange_locs])
                o_min_c = min([p[1] for p in orange_locs])
                o_max_c = max([p[1] for p in orange_locs])

                # Check collision
                if nc1 + 4 == o_min_c and abs(nr1 - o_min_r) <= 4:
                     # Kick
                     clear_area(o_min_r, o_max_r, o_min_c, o_max_c, 'w')
                     for r in range(o_min_r, o_max_r + 1):
                         for c in range(o_min_c + 8, o_max_c + 9):
                             if 0 <= r < H and 0 <= c < W:
                                 board[r][c] = 'O'
                     kicked = True

            clear_area(r1, r2, c1, c2, 'w')
            draw_player(nr1, nc1)

            if not kicked and action == 'RIGHT' and orange_locs:
                 o_min_r = min([p[0] for p in orange_locs])
                 expected_o_r = nr1 + 8
                 if abs(o_min_r - expected_o_r) <= 1:
