                     clear_area(o_min_r, o_max_r, o_min_c, o_max_c, 'w')
                     for r in range(o_min_r, o_max_r + 1):
                         for c in range(o_min_c + 1, o_max_c + 2):
                             if 0 <= r < H and 0 <= c < W:
                                 board[r][c] = 'O'

            update_ui()

    return [''.join(row) for row in board]

def predict(board_lines, action):
    n = len(board_lines)
    m = len(board_lines[0]) if n > 0 else 0
    board = [list(line) for line in board_lines]

    # 1. Update Timer (Column 63)
    if m == 64:
        last_col_idx = 63
        for r in range(n - 1):
            if board[r][last_col_idx] == 'Y':
                board[r][last_col_idx] = 'B'
                break

    # 2. Define Static Walls
    # S, Y are static. 
    # B is static if it touches the boundary (row 0, row 63, col 0, col 63) OR is part of a very large component (>20 cells).
    # Movable entities are small components of B, W, c.

    def get_movable_components(bd):
        visited = [[False]*m for _ in range(n)]
        components = []

        # First, identify static B regions to exclude them
        static_visited = [[False]*m for _ in range(n)]

        for r in range(n):
            for c in range(m):
                char = bd[r][c]
                if char in ['B', 'W', 'c'] and not visited[r][c]:
                    # Start BFS for this component
                    comp_cells = []
                    queue = [(r, c)]
                    visited[r][c] = True
                    is_static = False

                    while queue:
                        cr, cc = queue.pop(0)
                        comp_cells.append((cr, cc))

                        # Check if touching border
                        if cr == 0 or cr == n-1 or cc == 0 or cc == m-1:
                            is_static = True

                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc]:
                                nchar = bd[nr][nc]
                                # Connect same logical type? 
                                # Usually B/W form one player. c forms obstacles.
                                # In Sokoban-like, any non-wall color group is a unit.
                                # Here, let's assume B/W/c are all potentially movable if small.
                                # But they don't mix colors usually.
                                if nchar in ['B', 'W', 'c']:
                                    # Heuristic: Only connect if same primary color family?
                                    # Simpler: Connect all non-background, non-static-wall chars.
                                    # But S and Y are walls.
                                    if nchar != 'S' and nchar != 'Y':
                                        visited[nr][nc] = True
                                        queue.append((nr, nc))

                    # Determine if static
                    # If it touched border, it's static.
                    # If it's huge, it's likely static structure.
                    if is_static or len(comp_cells) > 50:
                        continue

                    # Check if contains only movable colors
                    has_movable_color = False
                    for cr, cc in comp_cells:
                        if bd[cr][cc] in ['B', 'W', 'c']:
                            has_movable_color = True
                            break

                    if has_movable_color:
                        components.append(comp_cells)

        return components

    movable_comps = get_movable_components(board)

    # Create a map from cell to component index for quick lookup during collision
    cell_to_comp = {}
    for idx, comp in enumerate(movable_comps):
        for r, c in comp:
            cell_to_comp[(r, c)] = idx

    directions = {
        'UP': (-1, 0),
        'DOWN': (1, 0),
        'LEFT': (0, -1),
        'RIGHT': (0, 1)
    }

    if action in directions and movable_comps:
        dr, dc = directions[action]

        # We need to simulate pushing.
        # Strategy: Try to move each component. If it hits another component, try to push that one.
        # Use recursion with memoization of "can_move" for current step.

        can_move_cache = {}

        def check_can_move(comp_idx, visited_stack=None):
            if visited_stack is None:
                visited_stack = set()

            if comp_idx in can_move_cache:
                return can_move_cache[comp_idx]

            if comp_idx in visited_stack:
                return False # Cycle detected, blocked

            visited_stack.add(comp_idx)

            comp = movable_comps[comp_idx]
            result = True

            for r, c in comp:
                nr, nc = r + dr, c + dc

                # Boundary check
                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    result = False
                    break

                target_char = board[nr][nc]

                # Static Wall check
                if target_char in ['S', 'Y']:
                    result = False
                    break

                # Empty space
                if target_char == 'b':
                    continue

                # Another movable component
                if (nr, nc) in cell_to_comp:
                    other_idx = cell_to_comp[(nr, nc)]
                    if other_idx == comp_idx:
                        continue # Internal
                    if not check_can_move(other_idx, visited_stack.copy()):
                        result = False
                        break
                else:
                    # Occupied by static B (not in movable comps)
                    if target_char == 'B':
                         # If it's a static B wall, block
                         result = False
                         break
                    elif target_char == 'W':
                         # Shouldn't happen if W is only in movable comps
                         pass

            can_move_cache[comp_idx] = result
            return result

        # Apply moves for all components that can move
        for idx, comp in enumerate(movable_comps):
            if check_can_move(idx):
                # Move this component
                for r, c in comp:
                    board[r][c] = 'b' # Clear old spot
                for r, c in comp:
                    nr, nc = r + dr, c + dc
                    board[nr][nc] = board_lines[r][c] # Set new spot with original color

    return ["".join(row) for row in board]

