        counts = {'W': 0, 'p': 0}
        coords = []
        for r in rows_range:
            for c in cols_range:
                val = get(r, c)
                if val == 'W' or val == 'p':
                    counts[val] += 1
                    coords.append((r, c))
        return counts, coords

