def predict(board_lines, action):
    # Convert to mutable list of lists
    board = [list(line) for line in board_lines]
    rows = len(board)
    cols = len(board[0]) if rows > 0 else 0

    # If no valid dimensions, return original
    if rows == 0 or cols == 0:
        return board_lines

    # Helper to check if cell is empty (black)
    def is_empty(r, c):
        return board[r][c] == 'B'

    # Process based on action
    if action in ["LEFT", "RIGHT", "UP", "DOWN"]:
        # We will simulate sliding tiles. 
        # Since exact block definitions vary, we'll try a pixel-level gravity simulation 
        # which often approximates the result for simple sliding puzzles.

        new_board = [['B'] * cols for _ in range(rows)]

        if action == "LEFT":
            for r in range(rows):
                write_idx = 0
                for c in range(cols):
                    if board[r][c] != 'B':
                        new_board[r][write_idx] = board[r][c]
                        write_idx += 1

        elif action == "RIGHT":
            for r in range(rows):
                write_idx = cols - 1
                for c in range(cols - 1, -1, -1):
                    if board[r][c] != 'B':
                        new_board[r][write_idx] = board[r][c]
                        write_idx -= 1

        elif action == "UP":
            for c in range(cols):
                write_idx = 0
                for r in range(rows):
                    if board[r][c] != 'B':
                        new_board[write_idx][c] = board[r][c]
                        write_idx += 1

        elif action == "DOWN":
            for c in range(cols):
                write_idx = rows - 1
                for r in range(rows - 1, -1, -1):
                    if board[r][c] != 'B':
                        new_board[write_idx][c] = board[r][c]
                        write_idx -= 1

        # Replace board with new_board
        board = new_board

    elif action == "RESET":
        # Cannot truly reset without history. Return as-is or assume static.
        # In many replay tests, RESET restores to start. But we only have current board.
        # We do nothing here to avoid data loss, effectively passing through.
        pass

    elif action == "UNDO":
        # Cannot undo without history. Pass through.
        pass

    elif action.startswith("MOUSE"):
        # Mouse clicks typically select or swap. Without target logic, pass through.
        pass

    elif action == "SPACE":
        # Space often confirms or rotates. Pass through.
        pass

    return [''.join(row) for row in board]
